mapper.select:
select top 1  from ${table}
where type = 2 and biz_type = #{bizType} and biz_id = #{bizId} and wx_userid = #{wxUserid}
order by id desc

select  from ${table}
where type = 2 and biz_type = #{bizType} and biz_id = #{bizId}
order by id desc

mapper.update:
update ${table}
set task_state = #{taskState},
    modedatamodifydatetime = #{modifyDatetime}
where type = 2 and task_id = #{taskId}

update ${table}
set task_id = #{newTaskId},
    modedatamodifydatetime = #{modifyDatetime}
where type = 2 and task_id = #{oldTaskId}

mapper.delete:
delete from ${table}
where type = 2 and modedatacreatedate < #{beforeDate}
   or (modedatacreatedate = #{beforeDate} and modedatacreatetime < #{beforeTime})
